pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 guess, uint256 blockOffset) public {
        // Ensure blockOffset is >= 2 so that settle() can be called after the commit block
        blockOffset = bound(blockOffset, 2, 100);

        // Fund the test contract with 1 ether for lockInGuess
        vm.deal(address(this), 1 ether);

        // Call lockInGuess
        c.lockInGuess{value: 1 ether}(guess);

        // Get the commit block number
        uint256 commitBlock = block.number + 1;

        // Mine blocks to reach settleBlock = commitBlock + blockOffset
        vm.roll(commitBlock + blockOffset);

        // Now call settle() and capture the balance before and after
        uint256 balanceBefore = address(this).balance;

        // Use try/catch to handle potential revert in the mutant
        try c.settle() {
            uint256 balanceAfter = address(this).balance;
            uint256 payment = balanceAfter - balanceBefore;
            // Rule: payment must be 0 or 2 ether, and must be 2 ether iff guess == keccak256(blockhash(commitBlock))
            bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(commitBlock)));
            bool shouldWin = (guess == expectedAnswer);
            // If shouldWin, payment must be 2 ether; if not, payment must be 0
            assertTrue((shouldWin && payment == 2 ether) || (!shouldWin && payment == 0), "Payment rule violated");
        } catch {
            // Revert is only allowed if the guess would have been wrong (mutant bug allows revert for correct guesses too)
            // But the property we assert: settle() must never revert
            assertTrue(false, "settle() should not revert");
        }
    }
}

