import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash) public {
        // Ensure contract has initial 1 ether (or deal if needed)
        vm.deal(address(c), 1 ether);
        // Fund the caller with 1 ether
        address caller = address(this);
        vm.deal(caller, 1 ether);

        // Call lockInGuess with 1 ether
        (bool successLock, ) = address(c).call{value: 1 ether}(abi.encodeWithSelector(c.lockInGuess.selector, hash));
        require(successLock, "lockInGuess failed");

        // The stored block number is the one that should be used for answer; we cannot read it directly (struct is internal). Instead, after settle we can check the balance change.
        // But we need a general rule: after calling lockInGuess, the answer is based on blockhash of block.number + 1.
        // We can test by simulating: warp to block + 1, then call settle, and assert that if the guess matches blockhash(block.number) the caller wins.
        // However the rule must be general: settle only pays if hash == blockhash(storedBlock). We can test by calling settle and checking that the balance increased exactly when hash == blockhash(block.number + 1).
        // To avoid state change, we snapshot.
        uint256 snapshot = vm.snapshot();
        // Move to next block
        vm.roll(block.number + 1);
        // Now block.number is the stored block
        uint256 balBefore = address(caller).balance;
        (bool okSettle, ) = address(c).call(abi.encodeWithSelector(c.settle.selector));
        require(okSettle, "settle failed");
        uint256 balAfter = address(caller).balance;
        bool paidOut = (balAfter - balBefore == 2 ether);
        bool expectedPay = (hash == keccak256(abi.encodePacked(blockhash(block.number))));

        assertTrue(paidOut == expectedPay, "settle payout mismatch");

        vm.revertTo(snapshot);
    }
}

