pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender.balance >= 1 ether);

        // Fund the sender and lock in a guess
        vm.deal(sender, 2 ether);
        vm.startPrank(sender);
        c.lockInGuess{value: 1 ether}(hash);

        // Warp to after the guess block so settle can be called
        (bool success, ) = address(c).staticcall(abi.encodeWithSelector(c.settle.selector));
        // Just warp arbitrarily far ahead to ensure block.number > guesses[msg.sender].block
        vm.warp(block.number + 100);

        // First settle succeeds
        c.settle();

        // Second settle should revert (in reference due to block reset)
        bool secondReverted = false;
        try c.settle() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        vm.stopPrank();

        assertTrue(secondReverted, "Second settle() did not revert");
    }
}
